function(){
  function clickTab(name){
    var tabs=document.querySelectorAll('div.creator-tab');
    for(var i=0;i<tabs.length;i++){
      var t=tabs[i];
      if(t.hasAttribute('data-hp-kind')||t.hasAttribute('button-hp-installed'))continue;
      var title=t.querySelector('span.title');
      if(!title||title.textContent.trim()!==name)continue;
      var r=t.getBoundingClientRect();
      if(r.left<-1000||r.top<-1000)continue;
      t.click();
      return true;
    }
    return false;
  }
  function clickText(text){
    var elems=document.querySelectorAll('button,[role="button"],span,div,a');
    for(var i=0;i<elems.length;i++){
      if((elems[i].textContent||'').trim()===text){
        var r=elems[i].getBoundingClientRect();
        if(r.width>0&&r.height>0){elems[i].click();return true;}
      }
    }
    return false;
  }
  if(!clickTab('写长文')){return {ok:false,error:'未找到写长文 Tab'};}
  return {ok:true,step:'tab'};
}

function(){
  var elems=document.querySelectorAll('button,[role="button"],span,div,a');
  for(var i=0;i<elems.length;i++){
    if((elems[i].textContent||'').trim()==='新的创作'){
      elems[i].click();
      return {ok:true};
    }
  }
  return {ok:false,error:'未找到新的创作'};
}

function(ctx){
  var title=String(ctx.title||'');
  var el=document.querySelector('textarea.d-text[placeholder="输入标题"]');
  if(!el){return {ok:false,error:'未找到长文标题框'};}
  var setter=Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype,'value').set;
  el.focus();
  setter.call(el,title);
  el.dispatchEvent(new Event('input',{bubbles:true}));
  el.dispatchEvent(new Event('change',{bubbles:true}));
  return {ok:true,length:title.length};
}

function(ctx){
  var list=ctx.images;
  if(!Array.isArray(list)||!list.length){return {skipped:true,count:0};}
  var editor=document.querySelector('div.ql-editor');
  if(!editor){return {ok:false,error:'未找到编辑器'};}
  function srcFor(p){
    if(/^https?:\/\//i.test(p))return p;
    if(p.indexOf('file://')===0)return p;
    return 'file://'+(p.indexOf('/')===0?'':'/')+p;
  }
  var n=0;
  for(var i=0;i<list.length;i++){
    var p=String(list[i]||'').trim();
    if(!p)continue;
    var img=document.createElement('img');
    img.src=srcFor(p);
    editor.appendChild(img);
    n++;
  }
  editor.dispatchEvent(new Event('input',{bubbles:true}));
  return {ok:true,count:n};
}

function(){
  var elems=document.querySelectorAll('button,[role="button"],span,div,a');
  for(var i=0;i<elems.length;i++){
    if((elems[i].textContent||'').trim()==='一键排版'){
      elems[i].click();
      return {ok:true};
    }
  }
  return {ok:false,error:'未找到一键排版'};
}

function(){
  var cards=document.querySelectorAll('.template-card');
  var names=[];
  for(var i=0;i<cards.length;i++){
    var t=cards[i].querySelector('.template-title');
    names.push(t?(t.textContent||'').trim():('Template '+i));
  }
  return {templates:names,count:names.length};
}
